// ---- CONFIGURE ----
// Free-text region tokens -> tenant id. Aliases are matched exactly first,
// then by substring for aliases of 5+ characters, so "REGIONA" and
// "REGION A CAMPUS" both resolve without "A" matching everything.
return [{ json: {
  spreadsheetId: "PAYMENT_STATUS_SPREADSHEET_ID",
  gracePeriodDays: 7,
  tenants: [
    { tenantId: 1001, aliases: ["RA", "REGIONA"] },
    { tenantId: 1002, aliases: ["RB", "REGIONB"] }
  ]
}}];

// Current month tab plus the previous one, fuzzy-matched on tab title.
const MONTHS_BACK = 2;
const out = [];
const meta = $json;
const titles = (meta.sheets || [])
  .map(s => (s && s.properties) ? s.properties.title : null)
  .filter(Boolean);
const norm = (s) => String(s).toLowerCase().replace(/[^a-z0-9]/g, "");
const monthsFull = ["january","february","march","april","may","june",
  "july","august","september","october","november","december"];

const nowIst = new Date(Date.now() + 19800000);
const Y = nowIst.getUTCFullYear();
const M = nowIst.getUTCMonth();

for (let k = 0; k < MONTHS_BACK; k++) {
  const d = new Date(Date.UTC(Y, M - k, 1));
  const full = monthsFull[d.getUTCMonth()];
  const abbr = full.slice(0, 3);
  const yFull = String(d.getUTCFullYear());
  const yShort = yFull.slice(2);
  let match = null;
  for (const t of titles) {
    const n = norm(t);
    if ((n.includes(full) || n.includes(abbr)) && (n.includes(yFull) || n.includes(yShort))) {
      match = t; break;
    }
  }
  if (!match) continue;
  out.push({ json: { spreadsheetId: meta.spreadsheetId, sheetName: match, isCurrent: k === 0 } });
}
return out;

// Compute DESIRED access state per person. This step never looks at what the
// platform currently says - that comparison happens later. Separating
// "what should be true" from "what is true" is what makes the workflow
// re-runnable: it derives the same desired state every time.
//
//   paid            -> active
//   unpaid, overdue -> archived  (only past the grace period)
//   unpaid, in grace-> no opinion, leave alone
const out = [];
const inputs = $input.all();
const picks = $('Pick Month Tabs').all();
const cfg = $('Config').first().json;

const colLetter = (n) => {
  let s = ""; n += 1;
  while (n > 0) { const r = (n - 1) % 26; s = String.fromCharCode(65 + r) + s; n = Math.floor((n - 1) / 26); }
  return s;
};
const isEmail = (e) => {
  if (!e || e.indexOf(" ") !== -1) return false;
  const at = e.indexOf("@"); if (at <= 0) return false;
  const dot = e.indexOf(".", at + 2);
  return dot > at + 1 && dot < e.length - 1;
};
const normB = (s) => String(s || "").toUpperCase().replace(/[^A-Z0-9]/g, "");
const tenantForToken = (tok) => {
  const n = normB(tok); if (!n) return null;
  for (const c of cfg.tenants) if (c.aliases.indexOf(n) !== -1) return c.tenantId;
  for (const c of cfg.tenants)
    for (const a of c.aliases)
      if (a.length >= 5 && n.indexOf(a) !== -1) return c.tenantId;
  return null;
};
// One person can belong to several regions ("RA / RB"), so this returns a list.
const resolveTenants = (raw) => {
  const orgs = [];
  for (const t of String(raw || "").split(/[/,&]+/)) {
    const o = tenantForToken(t);
    if (o && orgs.indexOf(o) === -1) orgs.push(o);
  }
  return orgs;
};
const parseDue = (s) => {
  const p = String(s || "").split(/[^0-9]+/).filter(Boolean);
  if (p.length < 3) return null;
  let d = +p[0], mo = +p[1], y = +p[2];
  if (y < 100) y += 2000;
  const dt = new Date(y, mo - 1, d);
  if (isNaN(dt.getTime())) return null;
  dt.setHours(0, 0, 0, 0);
  return dt;
};

const today = new Date(); today.setHours(0, 0, 0, 0);

for (let i = 0; i < inputs.length; i++) {
  const ctx = (picks[i] && picks[i].json) ? picks[i].json : {};
  const data = (inputs[i].json && inputs[i].json.values) ? inputs[i].json.values : [];
  if (!data || data.length < 2) continue;

  const headers = data[0].map(h => String(h == null ? "" : h).trim());
  const f = (l) => headers.findIndex(h => h.toLowerCase() === l.toLowerCase());
  const iEmail  = f("Email");
  const iStatus = f("Payment Status");
  const iName   = f("Name");
  const iDue    = f("Due Date");
  const iAction = f("Access Action");
  const iRegion = f("Region");
  const actionCol = iAction >= 0 ? colLetter(iAction) : null;
  if (!actionCol) continue;

  for (let r = 1; r < data.length; r++) {
    const row = data[r] || [];
    const g = (k) => (k >= 0 && row[k] != null) ? String(row[k]).trim() : "";
    const email = g(iEmail).toLowerCase();
    const status = g(iStatus);
    if (!isEmail(email) || !status) continue;

    let desired;
    if (status.toLowerCase() === "received") {
      desired = "active";
    } else if (ctx.isCurrent) {
      const due = parseDue(g(iDue));
      if (!due) continue;                         // unparseable date -> no opinion
      const daysPast = Math.floor((today - due) / 86400000);
      if (daysPast <= cfg.gracePeriodDays) continue;
      desired = "archived";
    } else {
      continue;   // only the current tab may archive; older tabs can reactivate
    }

    const tenants = resolveTenants(g(iRegion));
    if (!tenants.length) continue;

    const base = {
      spreadsheetId: ctx.spreadsheetId, sheetName: ctx.sheetName,
      rowNumber: r + 1, actionCol,
      email, personName: g(iName), status, desired, isCurrent: !!ctx.isCurrent
    };
    for (const t of tenants) out.push({ json: Object.assign({}, base, { tenantId: t }) });
  }
}
return out;

// desired vs observed -> the minimum set of calls that closes the gap.
// If they already agree, no call is emitted at all. This is what makes the
// workflow safe to run every day: a steady state produces zero writes.
const BASE = $env.LMS_API_BASE + "/api/v1";
const inputs = $input.all();
const ctxs = $('Desired State').all();

const groups = {};
for (let i = 0; i < inputs.length; i++) {
  const ctx = (ctxs[i] && ctxs[i].json) ? ctxs[i].json : {};
  if (!ctx.email) continue;
  const resp = inputs[i].json || {};
  const people = Array.isArray(resp.students) ? resp.students : [];
  const match = people.find(s => String((s && s.email) || "").toLowerCase().trim() === ctx.email);

  if (!groups[ctx.email]) groups[ctx.email] = { reps: [], observed: [] };
  groups[ctx.email].reps.push(ctx);
  groups[ctx.email].observed.push({
    tenantId: ctx.tenantId,
    found: !!match,
    userId: match ? match.user_id : null,
    isArchived: match ? (Number(match.is_archived) === 1) : null
  });
}

const out = [];
for (const email in groups) {
  const grp = groups[email];
  const rep = grp.reps.find(c => c.isCurrent) || grp.reps[0];
  const seen = {};

  for (const o of grp.observed) {
    if (!o.found || seen[o.tenantId]) continue;
    seen[o.tenantId] = 1;

    let action = null, url = null;
    if (rep.desired === "archived" && !o.isArchived) {
      action = "archive";
      url = BASE + "/remove/organization/student/" + o.userId;
    } else if (rep.desired === "active" && o.isArchived) {
      action = "unarchive";
      url = BASE + "/unarchive/student/" + o.userId;
    }
    if (!action) continue;   // already in the desired state -> emit nothing

    out.push({ json: {
      spreadsheetId: rep.spreadsheetId, sheetName: rep.sheetName,
      rowNumber: rep.rowNumber, actionCol: rep.actionCol,
      email, personName: rep.personName, status: rep.status,
      tenantId: o.tenantId, userId: o.userId, action, actionUrl: url
    }});
  }
}
return out;

// Same rule as everywhere else: only a confirmed 200 produces a write-back.
const out = [];
const inputs = $input.all();
const ctxs = $('Diff Desired vs Observed').all();
const date = new Date(Date.now() + 19800000).toISOString().slice(0, 10);

for (let i = 0; i < inputs.length; i++) {
  const r = inputs[i].json || {};
  const ctx = (ctxs[i] && ctxs[i].json) ? ctxs[i].json : {};
  const writeValue = (r.code === 200)
    ? (ctx.action === "archive" ? "Archived on " + date : "Unarchived on " + date)
    : "";
  out.push({ json: Object.assign({}, ctx, { writeValue }) });
}
return out;

// Collapse every confirmed change into ONE batchUpdate call rather than one
// HTTP request per row. On a busy day this is the difference between a few
// hundred Sheets writes and a single one.
const items = $input.all().filter(it => it.json && it.json.writeValue && it.json.actionCol);
if (!items.length) return [];
const spreadsheetId = items[0].json.spreadsheetId;
const data = items.map(it => ({
  range: "'" + it.json.sheetName + "'!" + it.json.actionCol + it.json.rowNumber,
  values: [[ it.json.writeValue ]]
}));
return [{ json: { spreadsheetId, body: { valueInputOption: "RAW", data } } }];
